"""Exercise installation-history readout using fields generated by this package."""
import json
from pathlib import Path
import tempfile
from types import SimpleNamespace
import unittest

import numpy as np

from run_history_construction import ROOT, run, torch
from construction_response import analyse
from compare_construction import compare
from compare_paired_space import compare as compare_space
from history_response import initial_model, read_state, restore_field, corrected_kernel
from refine_history import refine


class HistoryPackageTests(unittest.TestCase):
    def test_complete_references_readout_refinement_and_restart(self):
        with tempfile.TemporaryDirectory(prefix="history-test-", dir=ROOT / "results") as directory:
            output = Path(directory) / "run"
            args = SimpleNamespace(
                mesh="coarse", round_length=0.4, gap=0.6, rounds=2, width=6, seed=17,
                face_patch_span=0.2, front_local=True, support_patch_span=0.4,
                support_local=True, device="cpu", cpu_threads=1, initial_network=None,
                resume=False, resume_from=None, head_steps=1, head_solver="svd",
                head_rcond=1e-11, gauss_newton_steps=0, cg_iterations=20,
                scaled_lbfgs=False, release_step=0.5, iterations=0, tolerance=1e-12,
                archive_rounds=[2], accept_training_limit=True, output=output)
            self.assertEqual(run(args), 0)
            saved = torch.load(output / "checkpoint.pt", weights_only=True)
            self.assertIsNone(saved["pending"])
            self.assertEqual(len(saved["accepted"]["references"]), 3)
            self.assertFalse(saved["run"]["increments"][-1]["converged"])
            response = analyse(output, (-1.0, -0.2), face=0.8)
            self.assertEqual(len(response["complete_batches"]), 2)
            recorded = saved["run"]["increments"][-1]["batches"][1:]
            for batch, expected in zip(response["complete_batches"], recorded):
                self.assertAlmostEqual(batch["final_mean_thrust_kN_per_m"],
                                       expected["mean_thrust_kN_per_m"], places=8)
            for row in response["history"]:
                thrust = np.asarray(row["hoop_thrust_kN_per_m"], dtype=float)
                components = np.asarray(row["thrust_components_kN_per_m"], dtype=float)
                installed = np.isfinite(thrust)
                np.testing.assert_allclose(components[installed].sum(axis=1),
                                           thrust[installed], atol=2e-8)
            self.assertLess(response["summary"]["maximum_strain_stress_identity_difference_MPa"], 2e-10)
            comparison = compare([output], (-1.0, -0.2), face=0.8)
            paired = compare_space(comparison, comparison)
            np.testing.assert_array_equal(list(paired["spatial_changes_by_schedule"][0]
                                               ["percent_change"].values()), 0)
            json.dumps(comparison, allow_nan=False)
            with corrected_kernel():
                model, _ = initial_model()
            state = read_state(output / "round-002.npz")
            state["reference_bias"][0, 0, 2] += 0.1
            with self.assertRaises(AssertionError):
                restore_field(model, state)
            refine(SimpleNamespace(
                checkpoint=output / "round-002-before-final.pt",
                accepted_checkpoint=output / "round-002-checkpoint.pt",
                output=output / "refinement", device="cpu", cpu_threads=1,
                head_steps=0, head_solver="svd", head_rcond=1e-11,
                gauss_newton_steps=0, cg_iterations=20, iterations=0,
                scaled_lbfgs=False, support_local=False, tolerance=1e-12, resume=False))
            args.resume = True
            self.assertEqual(run(args), 0)
            restored = torch.load(output / "checkpoint.pt", weights_only=True)
            for key, value in saved["accepted"]["arrays"].items():
                torch.testing.assert_close(restored["accepted"]["arrays"][key], value, rtol=0, atol=0)
            for actual, expected in zip(restored["accepted"]["references"], saved["accepted"]["references"]):
                torch.testing.assert_close(actual["stress_bias"], expected["stress_bias"], rtol=0, atol=0)


if __name__ == "__main__":
    torch.set_num_threads(1)
    unittest.main()
